// The batch: subjects already delivered (a handshake, or a job read from the chain), one canonical HIRE each. The
// judge builds every evidence pack itself from DELIVERY + FACTS (schemas/GRADEABLE.md) — nothing here hands Jev a
// state. Pass { subjects: [{ handshake_id } | { chainId, jobId }], jobId, threshold } on the trigger, or run the demo set.
const t = $input.first().json || {};
const subjects = Array.isArray(t.subjects) && t.subjects.length ? t.subjects : [
  { handshake_id: 'hs_97dcf5942e294f7ca28efd0a' }, { handshake_id: 'hs_ec150f74dbe6568982c6c93d' }, { handshake_id: 'hs_c07ccb807a29b94dffb18459' },
];
return subjects.map((s) => {
  const hs = typeof s.handshake_id === 'string' && /^hs_[0-9a-f]{24}$/.test(s.handshake_id) ? s.handshake_id : null;
  const chainId = s.chainId != null ? Number(s.chainId) : hs ? 36927 : 8453;
  const id = hs ?? String(s.jobId);
  const job = hs ? { key: 'hs:' + hs, lane: 'handshake', chain_id: chainId, id: hs, contract: null }
    : { key: 'erc8183:' + chainId + ':' + id, lane: 'erc8183', chain_id: chainId, id, contract: '0x238e541bfefd82238730d00a2208e5497f1832e0' };
  return { json: {
    schema: 'taifoon.hire.v1', job, lane: job.lane, tenant: null, buyer: null, seller: null, seller_agent_key: null, seller_ids: [],
    evaluator: null, hook: null, evaluator_kind: null, task: null, required_skills: [], budget: null, funding: null,
    created_at: null, deadline: null, handshake_id: hs, offer_nonce: null, state: 'Delivered', ending: null,
    anchors: [{ kind: 'offchain', store: hs ? 'coordd:coordination_handshakes' : 'observatory', key: id, digest: null, anchored_by: null, what: 'the subject this batch grades' }],
    source: { kind: hs ? 'handshake' : 'observatory-job', url: hs ? 'https://www.taifoon.io/v1/handshake/' + hs : 'https://www.taifoon.io/v1/judge/evidence/' + chainId + '/' + id, read_at: Math.floor(Date.now() / 1000) },
  } };
});

// The batch outcome from the recorded verdicts — each item was composed under THRESHOLDS_v1 and recorded (decision.v2
// + jev.answer.v1) by Judge · answers; a hard fail was final at prepare. complete → Conformant, reject → NonConformant,
// needs_review → NoGrade (the verdict crate's batch mapping). Runs once per branch that reaches it; the batch record
// is keyed by jobId, so the last (complete) run is the one that stays.
const t = $('Grade a batch').first().json || {};
const jobId = t.jobId || 'batch-' + $execution.id;
const threshold = typeof t.threshold === 'number' ? t.threshold : 0.2;
const prepared = $('Judge · prepare').all().map((i) => i.json);
let answered = [];
try { answered = $('Judge · answers').all().map((i) => i.json); } catch (e) { answered = []; }
const items = [];
for (const p of prepared.filter((x) => x.hard_fail === true)) items.push({ item_id: p.subject, verdict: 'NonConformant', composed: 'reject', forced: 'hard_fail', mode: 'Deterministic', decision_id: null, answers_digest: null });
for (const a of answered) {
  const v = a.receipt && a.receipt.verdict;
  items.push({ item_id: (a.decision && a.decision.subject_id) || null, verdict: v === 'complete' ? 'Conformant' : v === 'reject' ? 'NonConformant' : 'NoGrade', composed: v || null, forced: null, mode: 'Calibrated',
    decision_id: a.decision ? a.decision.id : null, decision_digest: a.decision ? a.decision.digest : null, answers_digest: a.decision ? a.decision.answers_digest ?? null : null });
}
const conformant = items.filter((i) => i.verdict === 'Conformant').length, nonconformant = items.filter((i) => i.verdict === 'NonConformant').length, nograde = items.length - conformant - nonconformant;
const graded = conformant + nonconformant, failFraction = graded === 0 ? 1 : nonconformant / graded;
return [{ json: { jobId, mode: 'Calibrated', total: items.length, conformant, nonconformant, nograde, failFraction, threshold,
  verdict: graded === 0 ? 'NoGrade' : failFraction <= threshold ? 'Conformant' : 'NonConformant', items } }];
